EchoStation.Rendering.Editor.SceneSafetyGuard.RequireClean();
var rows=new Newtonsoft.Json.Linq.JArray();
foreach(var role in new[]{"Floor","Guard","Desk","Chair"}){var p=UnityEditor.AssetDatabase.LoadAssetAtPath<UnityEngine.GameObject>(EchoStation.InfiltrationArt.Editor.ArtSampleAssets.PathFor(role));var a=p.GetComponentInChildren<UnityEngine.Animator>();rows.Add(new Newtonsoft.Json.Linq.JObject{{"role",role},{"meshes",Newtonsoft.Json.Linq.JArray.FromObject(p.GetComponentsInChildren<UnityEngine.MeshFilter>(true).Select(f=>new {name=f.name,vertices=f.sharedMesh.vertexCount,path=UnityEditor.AssetDatabase.GetAssetPath(f.sharedMesh)}).ToArray())},{"animator",a!=null},{"clips",Newtonsoft.Json.Linq.JArray.FromObject(a&&a.runtimeAnimatorController?a.runtimeAnimatorController.animationClips.Select(c=>new {name=c.name,length=c.length,curves=UnityEditor.AnimationUtility.GetCurveBindings(c).Length}).ToArray():new object[0])},{"scripts",Newtonsoft.Json.Linq.JArray.FromObject(p.GetComponentsInChildren<UnityEngine.MonoBehaviour>(true).Select(c=>c.GetType().FullName).ToArray())}});}
return new {rows=rows,sourceClips=UnityEditor.AssetDatabase.LoadAllAssetsAtPath(EchoStation.InfiltrationArt.Editor.ArtSampleAssets.ThirdParty+"/lowpoly-robot/Robot.fbx").OfType<UnityEngine.AnimationClip>().Where(c=>!c.name.StartsWith("__")).Select(c=>new {name=c.name,length=c.length,curves=UnityEditor.AnimationUtility.GetCurveBindings(c).Length}).ToArray()};
